import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor conv2d_bf16_k3_cin3_forward(torch::Tensor x, torch::Tensor weight);
