conv_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_bf16.h>
#include <cstdint>
#include <c10/cuda/CUDAStream.h>

#include <mma.h>
#include <cute/tensor.hpp>

using namespace cute;
using namespace nvcuda;

constexpr int kThreads = 256;
constexpr int kInChannels = 3;
constexpr int kOutChannels = 32;
constexpr int kKernel = 3;
constexpr int kGemmM = 64;
constexpr int kGemmN = 32;
constexpr int kGemmK = 32;
constexpr int kKActual = kInChannels * kKernel * kKernel;
constexpr int kWarpTile = 16;
constexpr int kWarps = kThreads / 32;
static_assert(kKActual == 27, "Unexpected reduction size");
static_assert(kGemmK >= kKActual, "K tile must cover the padded reduction");
static_assert(kGemmN == kOutChannels, "N tile must cover all output channels");
static_assert(kGemmM % kWarpTile == 0, "M tile must be divisible by warp tile");
static_assert(kGemmN % kWarpTile == 0, "N tile must be divisible by warp tile");
static_assert(kWarps == (kGemmM / kWarpTile) * (kGemmN / kWarpTile),
              "One 16x16 warp tile per warp");
__global__ void __launch_bounds__(kThreads, 1)
conv2d_bf16_k3_cin3_kernel(
    const __nv_bfloat16* __restrict__ X,
    const __nv_bfloat16* __restrict__ W,
    __nv_bfloat16* __restrict__ Y,
    int height_in,
    int width_in,
    int height_out,
    int width_out,
    int64_t x_batch_stride,
    int64_t y_batch_stride)
{
  const int tid = threadIdx.x;
  const int batch = blockIdx.y;
  const int m0 = blockIdx.x * kGemmM;
  const int64_t pixels_per_image = (int64_t)height_out * width_out;
  const int64_t x_c_stride = (int64_t)height_in * width_in;
  const int64_t y_c_stride = (int64_t)height_out * width_out;
  const __nv_bfloat16* __restrict__ x_batch = X + (int64_t)batch * x_batch_stride;
  __nv_bfloat16* __restrict__ y_batch = Y + (int64_t)batch * y_batch_stride;
  // Implicit-GEMM tiles: A is MxK stored col-major, B is KxN stored col-major.
  // K = 27 is zero-padded to 32 so one 16x16x16 BF16 tensor-core step finishes the reduction.
  __shared__ __nv_bfloat16 smem_a[kGemmK * kGemmM];
  __shared__ __nv_bfloat16 smem_b[kGemmN * kGemmK];
  __shared__ float smem_c[kGemmM * kGemmN];
  const __nv_bfloat16 bf16_zero = __float2bfloat16_rn(0.0f);
  // Load A two output pixels per thread: halves the integer address
  // computation and issues a single 4-byte vector load whenever the
  // pixel pair stays in one input row and is 4-byte aligned.
  constexpr int kRowPairs = kGemmM / 2;
  for (int idx = tid; idx < kGemmK * kRowPairs; idx += kThreads) {
    const int k = idx / kRowPairs;
    const int r = (idx - k * kRowPairs) * 2;
    __nv_bfloat16 v0 = bf16_zero;
    __nv_bfloat16 v1 = bf16_zero;
    if (k < kKActual) {
      const int64_t global_m = (int64_t)m0 + r;
      if (global_m < pixels_per_image) {
        const int out_h = (int)(global_m / width_out);
        const int out_w = (int)(global_m - (int64_t)out_h * width_out);
        const int ci = k / (kKernel * kKernel);
        const int rem = k - ci * (kKernel * kKernel);
        const int kh = rem / kKernel;
        const int kw = rem - kh * kKernel;
        const __nv_bfloat16* src = x_batch + (int64_t)ci * x_c_stride +
                                   (int64_t)(out_h + kh) * width_in +
                                   (out_w + kw);
        const bool has_second =
            (r + 1 < kGemmM) && (global_m + 1 < pixels_per_image);
        if (has_second && (out_w + 1 < width_out) &&
            ((reinterpret_cast<uintptr_t>(src) & 0x3) == 0)) {
          const __nv_bfloat162 pair =
              *reinterpret_cast<const __nv_bfloat162*>(src);
          v0 = pair.x;
          v1 = pair.y;
        } else {
          v0 = src[0];
          if (has_second) {
            if (out_w + 1 < width_out) {
              v1 = src[1];
            } else {
              v1 = x_batch[(int64_t)ci * x_c_stride +
                           (int64_t)(out_h + 1 + kh) * width_in + kw];
            }
          }
        }
      }
    }
    __nv_bfloat162 spair;
    spair.x = v0;
    spair.y = v1;
    *reinterpret_cast<__nv_bfloat162*>(smem_a + k * kGemmM + r) = spair;
  }
  // Load B directly in the native [out_channel][k] order as col-major KxN.
  for (int idx = tid; idx < kGemmN * kGemmK; idx += kThreads) {
    const int n = idx / kGemmK;
    const int k = idx - n * kGemmK;
    __nv_bfloat16 value = bf16_zero;
    if (k < kKActual) {
      const int ci = k / (kKernel * kKernel);
      const int rem = k - ci * (kKernel * kKernel);
      const int kh = rem / kKernel;
      const int kw = rem - kh * kKernel;
      value = W[((int64_t)n * kInChannels + ci) * kKernel * kKernel +
                kh * kKernel + kw];
    }
    smem_b[idx] = value;
  }
  __syncthreads();
  const int warp = tid >> 5;
  const int warp_m = (warp >> 1) * kWarpTile;
  const int warp_n = (warp & 1) * kWarpTile;
  wmma::fragment<wmma::accumulator, kWarpTile, kWarpTile, kWarpTile, float> c_frag;
  wmma::fill_fragment(c_frag, 0.0f);
  // K tile is 32 (27 real + 5 zero-padded), so two 16x16x16 steps cover it.
  for (int k_step = 0; k_step < kGemmK; k_step += kWarpTile) {
    wmma::fragment<wmma::matrix_a, kWarpTile, kWarpTile, kWarpTile,
                   __nv_bfloat16, wmma::col_major> a_frag;
    wmma::fragment<wmma::matrix_b, kWarpTile, kWarpTile, kWarpTile,
                   __nv_bfloat16, wmma::col_major> b_frag;
    // A is MxK col-major (ldm = kGemmM): one K sub-tile = kGemmM elements.
    wmma::load_matrix_sync(a_frag, smem_a + k_step * kGemmM + warp_m, kGemmM);
    // B is KxN col-major (ldm = kGemmK): one K sub-tile = kWarpTile rows.
    wmma::load_matrix_sync(b_frag, smem_b + warp_n * kGemmK + k_step, kGemmK);
    wmma::mma_sync(c_frag, a_frag, b_frag, c_frag);
  }
  wmma::store_matrix_sync(smem_c + warp_m * kGemmN + warp_n,
                          c_frag, kGemmN, wmma::mem_row_major);
  __syncthreads();
  // Write NCHW output two pixels per thread; use one 4-byte vector store
  // when the pair stays in one output row and is 4-byte aligned.
  for (int idx = tid; idx < kGemmN * kRowPairs; idx += kThreads) {
    const int co = idx / kRowPairs;
    const int r = (idx - co * kRowPairs) * 2;
    const int64_t global_m = (int64_t)m0 + r;
    if (global_m < pixels_per_image) {
      const int out_h = (int)(global_m / width_out);
      const int out_w = (int)(global_m - (int64_t)out_h * width_out);
      __nv_bfloat16* dst = y_batch + (int64_t)co * y_c_stride +
                           (int64_t)out_h * width_out + out_w;
      const __nv_bfloat16 o0 =
          __float2bfloat16_rn(smem_c[r * kGemmN + co]);
      const bool has_second = (global_m + 1 < pixels_per_image);
      if (has_second && (out_w + 1 < width_out) &&
          ((reinterpret_cast<uintptr_t>(dst) & 0x3) == 0)) {
        __nv_bfloat162 pair;
        pair.x = o0;
        pair.y = __float2bfloat16_rn(smem_c[(r + 1) * kGemmN + co]);
        *reinterpret_cast<__nv_bfloat162*>(dst) = pair;
      } else {
        dst[0] = o0;
        if (has_second) {
          const __nv_bfloat16 o1 =
              __float2bfloat16_rn(smem_c[(r + 1) * kGemmN + co]);
          if (out_w + 1 < width_out) {
            dst[1] = o1;
          } else {
            y_batch[(int64_t)co * y_c_stride +
                    (int64_t)(out_h + 1) * width_out] = o1;
          }
        }
      }
    }
  }
}

torch::Tensor conv2d_bf16_k3_cin3_forward(torch::Tensor x, torch::Tensor weight) {
  TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
  TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
  TORCH_CHECK(x.scalar_type() == at::kBFloat16, "x must be bfloat16");
  TORCH_CHECK(weight.scalar_type() == at::kBFloat16, "weight must be bfloat16");
  TORCH_CHECK(x.dim() == 4, "x must have shape [N, C, H, W]");
  TORCH_CHECK(weight.dim() == 4, "weight must have shape [C_out, C_in, KH, KW]");

  const int64_t batch = x.size(0);
  const int64_t in_channels = x.size(1);
  const int64_t height_in = x.size(2);
  const int64_t width_in = x.size(3);

  TORCH_CHECK(in_channels == kInChannels, "Only 3 input channels are supported");
  TORCH_CHECK(weight.size(0) == kOutChannels, "Only 32 output channels are supported");
  TORCH_CHECK(weight.size(1) == kInChannels, "weight.size(1) must be 3");
  TORCH_CHECK(weight.size(2) == kKernel && weight.size(3) == kKernel,
              "Only 3x3 kernels are supported");
  TORCH_CHECK(height_in >= kKernel && width_in >= kKernel,
              "Input spatial dimensions must be at least 3");

  const int64_t height_out = height_in - kKernel + 1;
  const int64_t width_out = width_in - kKernel + 1;

  auto x_c = x.contiguous();
  auto weight_c = weight.contiguous();
  auto y = torch::empty({batch, kOutChannels, height_out, width_out}, x.options());

  const int64_t x_batch_stride =
      (int64_t)kInChannels * height_in * width_in;
  const int64_t y_batch_stride =
      (int64_t)kOutChannels * height_out * width_out;

  const __nv_bfloat16* x_ptr =
      reinterpret_cast<const __nv_bfloat16*>(x_c.data_ptr());
  const __nv_bfloat16* w_ptr =
      reinterpret_cast<const __nv_bfloat16*>(weight_c.data_ptr());
  __nv_bfloat16* y_ptr =
      reinterpret_cast<__nv_bfloat16*>(y.data_ptr());

  dim3 block(kThreads);
  const int64_t pixels_per_image = height_out * width_out;
  dim3 grid(
      (unsigned)((pixels_per_image + kGemmM - 1) / kGemmM),
      (unsigned)batch
  );

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  conv2d_bf16_k3_cin3_kernel<<<grid, block, 0, stream>>>(
      x_ptr,
      w_ptr,
      y_ptr,
      (int)height_in,
      (int)width_in,
      (int)height_out,
      (int)width_out,
      x_batch_stride,
      y_batch_stride
  );

  cudaError_t err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess,
              "conv2d_bf16_k3_cin3_kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
"""

