    name="cute_conv2d_bf16_k3_cin3_ext",
    cpp_sources=conv_cpp_decl,
    cuda_sources=conv_cuda_src,
    functions=["conv2d_bf16_k3_cin3_forward"],
    extra_cflags=["-O3", "-std=c++17"],
    extra_cuda_cflags=["-O3", "-std=c++17"],
    extra_include_paths=[
        "/root/cutegen_test/cutegen/cutlass/include",
        "/root/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


